VALUES ('DWA-M-205', '2013-03', 'TABELLE4', 'Merkmale und Eigenschaften von Niederdruck- und Mitteldruck-UV-Strahlern (figawa)', '§4.1.3.1, Tab. 4', NULL, ARRAY['strahlertyp']::text[], '[{"name":"hg_druck_hpa","type":"string"},{"name":"hg_druck_min","type":"number","unit":"hPa"},{"name":"hg_druck_max","type":"number","unit":"hPa"},{"name":"spektrum","type":"string"},{"name":"wellenlaenge_nm","type":"string"},{"name":"wellenlaenge_min","type":"number","unit":"nm"},{"name":"wellenlaenge_max","type":"number","unit":"nm"},{"name":"leistung_w","type":"string"},{"name":"leistung_min","type":"number","unit":"W"},{"name":"leistung_max","type":"number","unit":"W"},{"name":"leistungsdichte_w_cm","type":"string"},{"name":"leistungsdichte_min","type":"number","unit":"W/cm"},{"name":"leistungsdichte_max","type":"number","unit":"W/cm"},{"name":"uvc_anteil_pct","type":"string"},{"name":"uvc_anteil_min","type":"number","unit":"%"},{"name":"uvc_anteil_max","type":"number","unit":"%"},{"name":"oberflaechentemp_c","type":"string"},{"name":"oberflaechentemp_min","type":"number","unit":"°C"},{"name":"oberflaechentemp_max","type":"number","unit":"°C"},{"name":"nutzungsdauer_h","type":"string"},{"name":"nutzungsdauer_min","type":"number","unit":"h"},{"name":"nutzungsdauer_max","type":"number","unit":"h"}]'::jsonb, 'anhaltswert', '\hline Typische Leistungsaufnahme & W & $10 \mathrm{~W}-600 \mathrm{~W}$ & $1.000-30.000 \mathrm{~W}$ \\ — Im Angebot sind vom Anbieter die Nutzungsdauer der UV-Strahler einschließlich des Einflusses der Schaltvorgänge, die UV-C-Leistung der Strahler am Ende der Nutzungsdauer und der zugehörige Energieverbrauch der Strahler pro Kubikmeter Abwasserdurchfluss durch die UV-Anlage anzugeben und zu garantieren. Bezugsquellen, Preise und Nachweise zur längerfristigen Verfügbarkeit für UV-Ersatzstrahler sind zu benennen.', 'md_verified')
