VALUES ('DWA-M-205', '2013-03', 'S4_1_2_3', 'Erforderliche UV-Mindestbestrahlung nach Zielband (§4.1.2.3)', '§4.1.2.3', NULL, ARRAY['zielband']::text[], '[{"name":"dosis_min_j_m2","type":"number","unit":"J/m²"},{"name":"dosis_max_regel_j_m2","type":"number","unit":"J/m²"},{"name":"dosis_max_j_m2","type":"number","unit":"J/m²"}]'::jsonb, 'anhaltswert', 'Entsprechend den Anforderungen kann die notwendige Mindestbestrahlung aber auch höher liegen.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'mindestbestrahlung', '{"zielband":"mindestbestrahlung"}'::jsonb, NULL, 'Mindestbestrahlung 300–450 J/m² (Grenz- und Leitwerte 76/160/EWG, AFS 5–20 mg/l)', 0, '{"dosis_min_j_m2":300,"dosis_max_regel_j_m2":450,"dosis_max_j_m2":450}'::jsonb, 'Auf Grundlage der Grenz- und Leitwerte der früheren EG-Badegewässer-Richtlinie 76/160/EWG (Tabelle 1) wurden in der Vergangenheit Untersuchungen an Versuchsund Praxisanlagen mit Niederdruckstrahlern durchgeführt [10;13;14;18;19]. Danach beträgt die Mindestbestrahlung etwa $300 \mathrm{~J} / \mathrm{m}^{2}$ bis $450 \mathrm{~J} / \mathrm{m}^{2}$ zur sicheren Einhaltung der Grenz- und Leitwerte der EG-Badegewässer-Richtlinie für biologisch gereinigtes Abwasser bei einer Konzentration an abfiltrierbaren Stoffen von $5 \mathrm{mg} / \mathrm{l}$ bis $20 \mathrm{mg} / \mathrm{l}$.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_1_2_3'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'einzelfall_zehnerpotenz', '{"zielband":"einzelfall_zehnerpotenz"}'::jsonb, NULL, 'Unterschreitung der Leitwerte um eine Zehnerpotenz: 400–600 J/m², im Einzelfall bis 700 J/m²', 1, '{"dosis_min_j_m2":400,"dosis_max_regel_j_m2":600,"dosis_max_j_m2":700}'::jsonb, 'Entsprechend den Anforderungen kann die notwendige Mindestbestrahlung aber auch höher liegen. An der Isar wurde als Zielvorgabe die Unterschreitung der Leitwerte um eine Zehnerpotenz vorgegeben. Eine Auswertung der Daten von verschiedenen, im Betrieb befindlichen UVAnlagen zeigt eine Schwankungsbreite für die eingestellte Mindestbestrahlung von $400 \mathrm{~J} / \mathrm{m}^{2}$ bis $600 \mathrm{~J} / \mathrm{m}^{2}$ und im Einzelfall bis zu $700 \mathrm{~J} / \mathrm{m}^{2}$ [16]. Die Bemessungsvorgaben dieser UV-Anlagen für die Transmission liegen im Bereich > 60 \% bis > 70 \% (in der Regel > 65 \%) und für die abfiltrierbaren Stoffe bei $<10 \mathrm{mg} / \mathrm{l} \mathrm{bzw}$. zum Teil auch $<5 \mathrm{mg} / \mathrm{l}$.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_1_2_3'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_1_2_3' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-205', '2013-03', 'S3_3_LOGRED', 'Empfohlene Keimreduzierung (Log-Stufen) nach Nutzung und Bewirtschaftung (WHO, §3.3)', '§3.3', NULL, ARRAY['nutzung','bewirtschaftung']::text[], '[{"name":"empfehlung","type":"string"},{"name":"log_min","type":"number","unit":"log10"},{"name":"log_max","type":"number","unit":"log10"}]'::jsonb, 'anhaltswert', 'Für die uneingeschränkte Nutzung wird eine Keimreduzierung um 6 bis 7 Log-Stufen empfohlen (bezogen auf eine Rohabwasserbelastung von $10^{7}$ Escherichia coli in 100 ml ), für die eingeschränkte Nutzung um 4 LogStufen (bei arbeitsintensiver Bewirtschaftung) bzw. um 3 Log-Stufen (bei hoch mechanisierter Bewirtschaftung).', 'md_verified')
