INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-205', '2013-03', 'S4_3_3_2', 'Ozonerzeugung nach Einsatzgas: spezifischer Energieverbrauch, Sauerstoffbedarf, Ozonanteil, Ozonertrag (§4.3.3.2)', '§4.3.3.2', NULL, ARRAY['einsatzgas']::text[], '[{"name":"spez_energie_kwh_kg","type":"number","unit":"kWh/kg O3"},{"name":"aufschlag_pct","type":"number","unit":"%"},{"name":"o2_pro_o3_kg","type":"number","unit":"kg O2/kg O3"},{"name":"o3_anteil_min_pct","type":"number","unit":"%"},{"name":"o3_anteil_max_pct","type":"number","unit":"%"},{"name":"o3_pro_m3_o2_min_g","type":"number","unit":"g/m³ O2"},{"name":"o3_pro_m3_o2_max_g","type":"number","unit":"g/m³ O2"}]'::jsonb, 'anhaltswert', 'Anlagen für Ozonleistungen über $1 \mathrm{~kg} / \mathrm{h}$ arbeiten bei einer Spannung von ca. 10 kV und einer Frequenz von ca. 600 Hz . Für 1 kg Ozon werden etwa 10 kg Sauerstoff benötigt (bei ca. $10 \%$ bis $13 \%$ Ozon im erzeugten Gasgemisch). Pro Kubikmeter Reinsauerstoff können so ca. 150 g bis 200 g Ozon erzeugt werden. Der spezifische Energieverbrauch der Ozonerzeugung aus Reinsauerstoff beträgt etwa $10 \mathrm{kWh} / \mathrm{kg}$ Ozon. Bei Verwendung von Luft beträgt er ca. $60 \%$ mehr.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
