INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-205', '2013-03', 'S4_4_2', 'Chlorung nach Chlorungsmittel: Dosis, Kontaktzeit, pH, Restchlor, Sicherheitsgrenzen (§4.4.2)', '§4.4.2', NULL, ARRAY['chlormittel']::text[], '[{"name":"dosis_min","type":"number"},{"name":"dosis_max","type":"number"},{"name":"dosis_unit","type":"string"},{"name":"dosis_sandfiltriert_min","type":"number","unit":"g/m³"},{"name":"dosis_sandfiltriert_max","type":"number","unit":"g/m³"},{"name":"kontaktzeit_min","type":"number","unit":"min"},{"name":"kontaktzeit_max","type":"number","unit":"min"},{"name":"kontaktzeit_text","type":"string"},{"name":"ph_min","type":"number"},{"name":"ph_max","type":"number"},{"name":"restchlor_mg_l","type":"number","unit":"mg/l"},{"name":"loesung_g_l_min","type":"number","unit":"g/l"},{"name":"loesung_g_l_max","type":"number","unit":"g/l"},{"name":"explosiv_ab_vol_pct","type":"number","unit":"Vol.-%"},{"name":"log_stufen","type":"number","unit":"log10"}]'::jsonb, 'anhaltswert', 'Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'chlorgas', '{"chlormittel":"chlorgas"}'::jsonb, NULL, 'Chlorgas (Cl₂): 1–20 mg/l freies Chlor, 15 bis 30 Minuten', 0, '{"dosis_min":1,"dosis_max":20,"dosis_unit":"mg/l freies Chlor","dosis_sandfiltriert_min":null,"dosis_sandfiltriert_max":null,"kontaktzeit_min":15,"kontaktzeit_max":30,"kontaktzeit_text":"15 bis 30 Minuten","ph_min":6,"ph_max":8,"restchlor_mg_l":0.2,"loesung_g_l_min":null,"loesung_g_l_max":null,"explosiv_ab_vol_pct":null,"log_stufen":null}'::jsonb, 'Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_4_2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'natriumhypochlorit', '{"chlormittel":"natriumhypochlorit"}'::jsonb, NULL, 'Natriumhypochlorit (NaOCl, Chlorbleichlauge): 1–20 mg/l freies Chlor, 15 bis 30 Minuten', 1, '{"dosis_min":1,"dosis_max":20,"dosis_unit":"mg/l freies Chlor","dosis_sandfiltriert_min":null,"dosis_sandfiltriert_max":null,"kontaktzeit_min":15,"kontaktzeit_max":30,"kontaktzeit_text":"15 bis 30 Minuten","ph_min":6,"ph_max":8,"restchlor_mg_l":0.2,"loesung_g_l_min":null,"loesung_g_l_max":null,"explosiv_ab_vol_pct":null,"log_stufen":null}'::jsonb, 'Bei Anwendung von Chlorgas wird am Einsatzort eine Chlorlösung aus Chlorgas und Wasser hergestellt und dem Abwasser zudosiert (indirekte Chlorung). Chlorgasdosiergeräte (Bild 9) arbeiten nach dem VakuumInjektorprinzip. Die Regelung der Zugabe muss sowohl mengenproportional als auch entsprechend der Chlorzehrung (Restchlorgehalt) erfolgen. Je nach dem Gehalt an organischen Stoffen im Abwasser sind 1 mg bis 20 mg freies Chlor pro Liter, eine gründliche Durchmischung sowie eine Kontaktzeit von 15 bis 30 Minuten erforderlich. Eine geregelte Desinfektion ist nur dann gewährleistet, wenn ein pH -Bereich zwischen 6 und 8 eingehalten wird.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_4_2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'chlordioxid', '{"chlormittel":"chlordioxid"}'::jsonb, NULL, 'Chlordioxid (ClO₂): 5–10 g/m³, wenige Minuten', 2, '{"dosis_min":5,"dosis_max":10,"dosis_unit":"g/m³","dosis_sandfiltriert_min":1,"dosis_sandfiltriert_max":5,"kontaktzeit_min":null,"kontaktzeit_max":null,"kontaktzeit_text":"wenige Minuten","ph_min":null,"ph_max":null,"restchlor_mg_l":null,"loesung_g_l_min":1,"loesung_g_l_max":3,"explosiv_ab_vol_pct":30,"log_stufen":3}'::jsonb, 'Chlordioxid muss an Ort und Stelle hergestellt und sofort verbraucht werden, da es in Konzentration über 30 Volumenprozent explosiv ist und die Lösung schnell zerfällt. Dazu stehen mehrere Verfahren zur Verfügung. Beim Chlorit-Chlor-Verfahren wird Chlorwasser mit saurem pHWert ( $<2$ ) mit 10 \%iger Natriumchloritlösung zur Reaktion gebracht. Beim häufiger eingesetzten Chlorit-Salzsäure-Verfahren wird Natriumchlorit mit Salzsäure zu Chlordioxid umgesetzt. Ein weiteres Herstellungsverfahren geht von Natriumchlorit und Natriumperoxodisulfat aus. Da das erzeugte Chlordioxid als Gas nicht beständig ist, muss unmittelbar vor der Anwendung eine wässrige Lösung mit 1 g bis 3 g Chlordioxid pro Liter zubereitet werden. Die Zugabe kann im Durchflussverfahren mit dem Ansaug-Injektorsystem oder über Membranpumpen erfolgen. Die Dosierung erfolgt mengenproportional in Abhängigkeit vom Chlordioxidüberschuss im Wasser und ist von der organischen Belastung des Abwassers und der erforderlichen Keimreduktionsrate abhängig. Bei Verwendung von gereinigtem Abwasser als Betriebswasser in Kläranlagen sind etwa 5 g bis 10 g Chlordioxid pro Kubikmeter Abwasser zur Reduktion der Fäkalindikatorbakterien um drei Zehnerpotenzen notwendig, bei sandfiltriertem Abwasser mit geringer Restverschmutzung nur $1 \mathrm{~g} / \mathrm{m}^{3}$ bis $5 \mathrm{~g} / \mathrm{m}^{3}$. Die erforderliche Einwirkzeit beträgt wenige Minuten.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_4_2'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_4_2' AND verification_status = 'imported_unverified';
INSERT INTO regulation_tables (standard_code, edition, table_code, title_de, clause_reference, page_ref, key_columns, value_columns, override_policy, override_quote, verification_status)
VALUES ('DWA-M-205', '2013-03', 'S4_3_3_4', 'Restozonentfernung aus dem Abgas: thermisch / katalytisch (§4.3.3.4)', '§4.3.3.4', NULL, ARRAY['verbrennung_typ']::text[], '[{"name":"temp_min_c","type":"number","unit":"°C"},{"name":"temp_max_c","type":"number","unit":"°C"},{"name":"haltezeit_min_s","type":"number","unit":"s"},{"name":"restozon_max_mg_m3","type":"number","unit":"mg/m³"}]'::jsonb, 'locked', 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.', 'md_verified')
ON CONFLICT (standard_code, edition, table_code) DO UPDATE SET title_de = EXCLUDED.title_de, clause_reference = EXCLUDED.clause_reference, page_ref = EXCLUDED.page_ref, key_columns = EXCLUDED.key_columns, value_columns = EXCLUDED.value_columns, override_policy = EXCLUDED.override_policy, override_quote = EXCLUDED.override_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'thermisch', '{"verbrennung_typ":"thermisch"}'::jsonb, NULL, 'thermisch: Erhitzen auf 350 °C über mindestens 2 Sekunden', 0, '{"temp_min_c":350,"temp_max_c":null,"haltezeit_min_s":2,"restozon_max_mg_m3":0.02}'::jsonb, 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_3_3_4'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
INSERT INTO regulation_table_rows (table_id, row_key, keys, group_label, label_de, order_index, row_values, verbatim_quote)
SELECT id, 'katalytisch', '{"verbrennung_typ":"katalytisch"}'::jsonb, NULL, 'katalytisch: bei 60 °C bis 80 °C', 1, '{"temp_min_c":60,"temp_max_c":80,"haltezeit_min_s":null,"restozon_max_mg_m3":0.02}'::jsonb, 'Aufgrund seiner toxischen Eigenschaften muss das im Abgas der Anlagen enthaltene Restozon vor der Ableitung ins Freie abgesaugt und gezielt auf eine Konzentration von maximal $0,02 \mathrm{mg} / \mathrm{m}^{3}$ vermindert werden (Merkblatt DVGW W 625). Dies kann thermisch (Erhitzen auf $350^{\circ} \mathrm{C}$ über mindestens 2 Sekunden) oder katalytisch (bei $60^{\circ} \mathrm{C}$ bis $80^{\circ} \mathrm{C}$ ) erfolgen.' FROM regulation_tables WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_3_3_4'
ON CONFLICT (table_id, row_key) DO UPDATE SET keys = EXCLUDED.keys, group_label = EXCLUDED.group_label, label_de = EXCLUDED.label_de, order_index = EXCLUDED.order_index, row_values = EXCLUDED.row_values, verbatim_quote = EXCLUDED.verbatim_quote;
UPDATE regulation_tables SET verification_status = 'md_verified' WHERE standard_code = 'DWA-M-205' AND edition = '2013-03' AND table_code = 'S4_3_3_4' AND verification_status = 'imported_unverified';
COMMIT;
